using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Reflection.Emit;using System.Runtime.Serialization;using System.Web.Script.Serialization;
public static class VerifyManaged {
 static string root;static string[] paths;static JavaScriptSerializer json=new JavaScriptSerializer(){MaxJsonLength=int.MaxValue};
 static object Instance(Type t){if(!t.IsAbstract)return FormatterServices.GetUninitializedObject(t);var ab=AppDomain.CurrentDomain.DefineDynamicAssembly(new AssemblyName("Fixture"+Guid.NewGuid().ToString("N")),AssemblyBuilderAccess.Run);var tb=ab.DefineDynamicModule("Fixture").DefineType("Concrete",TypeAttributes.Public,t);foreach(var m in t.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Where(x=>x.IsAbstract)){if(m.IsGenericMethodDefinition)throw new Exception("Generic abstract fixture unsupported");var mb=tb.DefineMethod(m.Name,MethodAttributes.Public|MethodAttributes.Virtual|MethodAttributes.HideBySig,m.ReturnType,m.GetParameters().Select(x=>x.ParameterType).ToArray());var il=mb.GetILGenerator();if(m.ReturnType!=typeof(void)){if(m.ReturnType.IsValueType){var local=il.DeclareLocal(m.ReturnType);il.Emit(OpCodes.Ldloca,local);il.Emit(OpCodes.Initobj,m.ReturnType);il.Emit(OpCodes.Ldloc,local);}else il.Emit(OpCodes.Ldnull);}il.Emit(OpCodes.Ret);tb.DefineMethodOverride(mb,m);}return FormatterServices.GetUninitializedObject(tb.CreateType());}
 static object[] Values(Type t){var u=t.IsEnum?Enum.GetUnderlyingType(t):t;if(u==typeof(bool))return new object[]{false,true};if(u==typeof(float))return new object[]{0f,-0f,.25f,-13.5f,1024.125f};if(u==typeof(double))return new object[]{0d,-0d,.25d,-13.5d,1024.125d};if(u.IsPrimitive){var vs=new List<int>{0,1,7,127};if(u==typeof(sbyte)||u==typeof(short)||u==typeof(int)||u==typeof(long))vs.AddRange(new[]{-1,-17});return vs.Select(x=>t.IsEnum?Enum.ToObject(t,x):Convert.ChangeType(x,u)).ToArray();}object instance;if(t.IsArray)instance=Array.CreateInstance(t.GetElementType(),2);else if(t==typeof(string))instance="Native recovery fixture";else instance=FormatterServices.GetUninitializedObject(t);return new[]{null,instance};}
 public static int Main(string[] args){root=args[0];paths=new[]{Path.Combine(root,"patched"),args[1],args[2],args[3]};AppDomain.CurrentDomain.AssemblyResolve+=(o,e)=>{string simple=new AssemblyName(e.Name).Name;if(simple=="System.Core")return typeof(Enumerable).Assembly;string name=simple+".dll";foreach(var p in paths){string f=Path.Combine(p,name);if(File.Exists(f))return Assembly.LoadFrom(f);}return null;};foreach(var f in Directory.GetFiles(Path.Combine(root,"patched"),"*.dll").OrderBy(x=>x.Contains("KANAI.HybridCollision")?0:1))Assembly.LoadFrom(f);var rows=((object[])json.DeserializeObject(File.ReadAllText(Path.Combine(root,"candidates.json")))).Cast<Dictionary<string,object>>();var results=new List<object>();int pass=0,failed=0,cases=0;
 foreach(var row in rows){string signature=(string)row["signature"];Console.WriteLine("CHECK "+signature);Console.Out.Flush();try{var a=Assembly.LoadFrom(Path.Combine(root,"patched",(string)row["assembly"]+".dll"));if(!a.Location.StartsWith(Path.Combine(root,"patched"),StringComparison.OrdinalIgnoreCase))throw new Exception("Wrong assembly loaded: "+a.Location);var t=a.GetType(((string)row["type"]).Replace('/','+'),true);var obj=Instance(t);var kind=(string)row["kind"];string name=signature.Substring(signature.IndexOf("::")+2);name=name.Substring(0,name.IndexOf('('));var flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static|BindingFlags.DeclaredOnly;int testCount=0;
 if(row["field"]!=null){var fdata=(Dictionary<string,object>)row["field"];var f=t.GetField((string)fdata["name"],flags);var m=t.GetMethod(name,flags,null,kind=="instance_field_getter"?Type.EmptyTypes:new[]{f.FieldType},null);foreach(var value in Values(f.FieldType)){if(kind=="instance_field_getter"){f.SetValue(obj,value);object got=m.Invoke(obj,null);if(!object.Equals(got,value)||(!f.FieldType.IsValueType&&!Object.ReferenceEquals(got,value)))throw new Exception("Getter mismatch value="+value+" got="+got+" assembly="+a.Location+" methodBytes="+BitConverter.ToString(m.GetMethodBody().GetILAsByteArray()));}else{m.Invoke(obj,new[]{value});object got=f.GetValue(obj);if(!object.Equals(got,value))throw new Exception("Setter mismatch value="+value+" got="+got+" assembly="+a.Location+" methodBytes="+BitConverter.ToString(m.GetMethodBody().GetILAsByteArray()));}testCount++;}}
 else{var m=t.GetMethod(name,flags,null,Type.EmptyTypes,null);var got=m.Invoke(obj,null);if(Convert.ToInt64(got)!=Convert.ToInt64(row["constant"]))throw new Exception("Constant mismatch");testCount++;}
 results.Add(new{signature=signature,status="pass",cases=testCount});pass++;cases+=testCount;}
 catch(Exception ex){failed++;results.Add(new{signature=signature,status="failed",error=ex.ToString()});Console.WriteLine("FAILED "+ex.GetType().Name+": "+ex.Message);}}
 File.WriteAllText(Path.Combine(root,"managed-execution-check.json"),json.Serialize(new{methodsPassed=pass,methodsFailed=failed,casesPassed=cases,environment="Unity2023 Mono standalone reflection, target package/type dependencies, uninitialized synthetic instances; no Unity game lifecycle invoked",results=results}));Console.WriteLine("Managed checks: "+pass+" passed "+failed+" failed, "+cases+" cases.");return failed==0?0:1;}
}

